/* @autogenerated */
import {
  EditConflict,
  FieldMerge,
  FieldMergeChoice,
  FieldMergeState,
  ThreeWayMergeOptions,
} from './edit-conflict.model';

const DEFAULT_IGNORE = ['version', 'uid'];

/** Prefijo de fecha ISO-8601 (`YYYY-MM-DD…`): solo esas cadenas se comparan como instante. */
const ISO_DATE = /^\d{4}-\d{2}-\d{2}/;

/**
 * Compara campo a campo (primer nivel) las tres versiones y decide qué se fusiona solo y qué necesita al usuario.
 * Los campos ignorados no aparecen: `applyMerge` los toma de `current`.
 */
export function threeWayMerge<T>(conflict: EditConflict<T>, options: ThreeWayMergeOptions = {}): FieldMerge[] {
  const ignore = options.ignore ?? DEFAULT_IGNORE;
  const original = asRecord(conflict.original);
  const sent = asRecord(conflict.sent);
  const current = asRecord(conflict.current);
  const fields = new Set([...Object.keys(original), ...Object.keys(sent), ...Object.keys(current)]);
  return [...fields]
    .filter((field) => !ignore.includes(field))
    .map((field) => {
      const state = mergeState(original[field], sent[field], current[field]);
      return chooseMerge(
        { field, original: original[field], sent: sent[field], current: current[field], state, choice: null },
        state === 'conflict' ? null : state === 'mine' ? 'sent' : 'current',
      );
    });
}

/** Copia del campo con la versión elegida (o sin elegir, con `null`). */
export function chooseMerge(merge: FieldMerge, choice: FieldMergeChoice | null): FieldMerge {
  const copy: FieldMerge = { ...merge, choice };
  if (choice) {
    copy.resolved = merge[choice];
  } else {
    delete copy.resolved;
  }
  return copy;
}

/** Hay algún campo en conflicto sin resolver. */
export function hasPendingConflicts(merges: FieldMerge[]): boolean {
  return merges.some((merge) => !merge.choice);
}

/**
 * Valor final: `current` con el `resolved` de cada campo y la `version` de `current`.
 * Lanza si queda algún conflicto sin resolver.
 */
export function applyMerge<T>(conflict: EditConflict<T>, merges: FieldMerge[]): T {
  const pending = merges.filter((merge) => !merge.choice).map((merge) => merge.field);
  if (pending.length) {
    throw new Error('Unresolved edit conflicts: ' + pending.join(', '));
  }
  const current = asRecord(conflict.current);
  const result: Record<string, unknown> = { ...current };
  merges.forEach((merge) => {
    result[merge.field] = merge.resolved;
  });
  if ('version' in current) {
    result['version'] = current['version'];
  }
  return result as T;
}

function mergeState(original: unknown, sent: unknown, current: unknown): FieldMergeState {
  const mine = !sameValue(sent, original);
  const theirs = !sameValue(current, original);
  if (!mine && !theirs) {
    return 'unchanged';
  }
  if (mine && !theirs) {
    return 'mine';
  }
  if (!mine && theirs) {
    return 'theirs';
  }
  return sameValue(sent, current) ? 'same' : 'conflict';
}

/**
 * Igualdad estructural tolerante al formato del cable: `null`/`undefined`/`''`/`[]` son equivalentes, las
 * referencias se comparan por su `$ref`, las fechas por instante (también contra su cadena ISO-8601) y los arrays y
 * objetos por contenido.
 */
export function sameValue(a: unknown, b: unknown): boolean {
  if (a === b) {
    return true;
  }
  const emptyA = isEmpty(a);
  const emptyB = isEmpty(b);
  if (emptyA || emptyB) {
    return emptyA && emptyB;
  }
  if (a instanceof Date || b instanceof Date) {
    const timeA = toTime(a);
    const timeB = toTime(b);
    return timeA !== undefined && timeA === timeB;
  }
  if (isReference(a) || isReference(b)) {
    return isReference(a) && isReference(b) && a.$ref === b.$ref;
  }
  if (Array.isArray(a) || Array.isArray(b)) {
    return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((v, i) => sameValue(v, b[i]));
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
    return [...keys].every((key) => sameValue(a[key], b[key]));
  }
  return false;
}

function isEmpty(value: unknown): boolean {
  return value === null || value === undefined || value === '' || (Array.isArray(value) && value.length === 0);
}

function isReference(value: unknown): value is { $ref: unknown } {
  return isPlainObject(value) && '$ref' in value;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value) && !(value instanceof Date);
}

function toTime(value: unknown): number | undefined {
  if (value instanceof Date) {
    return value.getTime();
  }
  if (typeof value === 'string' && ISO_DATE.test(value)) {
    const time = Date.parse(value);
    return isNaN(time) ? undefined : time;
  }
  return undefined;
}

function asRecord(value: unknown): Record<string, unknown> {
  return isPlainObject(value) ? value : {};
}
